$exitFile = Join-Path $Work "exit-$RunId.txt"
$env:GIT_CONFIG_COUNT = '1'
$env:GIT_CONFIG_KEY_0 = 'safe.directory'
$env:GIT_CONFIG_VALUE_0 = '*'

"READ $((Get-Date).ToString('s')) host=$env:COMPUTERNAME user=$env:USERNAME"
"WORKTREE HEAD $((git -C $Worktree rev-parse HEAD 2>&1) -join ' ')"
"PROOF $(if (Test-Path -LiteralPath $proof) { (Get-Content -LiteralPath $proof -Raw).Trim() } else { '(absent)' })"
