    $lines = @(Get-Content -LiteralPath $log)
    "LOG lines=$($lines.Count)"
    $lines | Where-Object { $_ -match 'Integration lane (precondition|filter)|Passed!|Failed!|Skipped:|Total tests|Build (succeeded|failed)|MigrationIntegrationTests\s|InstallTestDependencies\s' } | ForEach-Object { "  LOG $_" }
