        $nsm = [System.Xml.XmlNamespaceManager]::new($doc.NameTable)
        $nsm.AddNamespace('t', $doc.DocumentElement.NamespaceURI)
        $c = $doc.SelectSingleNode('//t:ResultSummary/t:Counters', $nsm)
        "TRX $($trx.FullName.Substring($trxRoot.Length)) total=$($c.GetAttribute('total')) executed=$($c.GetAttribute('executed')) passed=$($c.GetAttribute('passed')) failed=$($c.GetAttribute('failed')) notExecuted=$($c.GetAttribute('notExecuted'))"
        foreach ($r in $doc.SelectNodes('//t:UnitTestResult[@outcome!="Passed"]', $nsm)) {
            $m = $r.SelectSingleNode('t:Output/t:ErrorInfo/t:Message', $nsm)
            $msg = if ($null -ne $m) { ($m.InnerText -replace '\s+', ' ').Trim() } else { '' }
            if ($msg.Length -gt 400) { $msg = $msg.Substring(0, 400) }
            "  $($r.GetAttribute('outcome')) $($r.GetAttribute('testName')) :: $msg"
        }
    }
}
else { "NO-TRX $trxRoot" }
if ($ended -and $task) {
    Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
    "TASK REMOVED $TaskName present-after=$([bool](Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue))"
}
"END $((Get-Date).ToString('s'))"

